declare const _default: "\n/** \u0444\u0443\u043D\u043A\u0446\u0438\u044F \u043F\u043E\u0438\u0441\u043A\u0430 \u0441\u0432\u044F\u0437\u0430\u043D\u043D\u044B\u0445 \u0431\u0430\u0440\u043E\u0432 */ \nconst findNestedBars = (barId: string | number, listBars: (string | number)[] = []): (string | number)[] => {\n  const childrenBar = timelineData.find(el => el.dependingBarIds?.includes(barId))\n\n  if (!childrenBar) return listBars\n\n  listBars.push(childrenBar.id)\n\n  if (childrenBar?.dependingBarIds?.length) {\n    listBars = findNestedBars(childrenBar.id, listBars)\n  }\n\n  return listBars\n}\n\nconst RenderGantt = () => {\n  const [selectedBars, setSelectedBars] = useState<(string | number)[]>([])\n  \n  /** \u0441\u043E\u0431\u044B\u0442\u0438\u0435 \u043A\u043B\u0438\u043A\u0430 \u043D\u0430 \u0431\u0430\u0440 */\n  const handleClickBar = (e: MouseEvent<HTMLDivElement>, barId: string | number) => {\n    e.preventDefault()\n    e.stopPropagation()\n  \n    // \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u044B\u0439 \u043A\u043B\u0438\u043A \u043D\u0430 \u0431\u0430\u0440\u0435 \u0441\u043D\u0438\u043C\u0430\u0435\u0442 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435\n    if (barId === selectedBars[0]) {\n      setSelectedBars([])\n  \n      return\n    }\n  \n    // \u043D\u0430\u0445\u043E\u0434\u0438\u043C \u0432\u0441\u0435 \u0441\u0432\u044F\u0437\u0430\u043D\u043D\u044B\u0435 \u0431\u0430\u0440\u044B \u0438 \u0432\u044B\u0434\u0435\u043B\u044F\u0435\u043C \u0438\u0445\n    const nestedBarIds = findNestedBars(barId)\n  \n    setSelectedBars([barId, ...nestedBarIds])\n  }\n  \n  /** \u0430\u0442\u0440\u0438\u0431\u0443\u0442\u044B \u0431\u0430\u0440\u0430 \u0441\u043E \u0441\u0442\u0438\u043B\u044F\u043C\u0438 \u0438 \u0441\u043B\u0443\u0448\u0430\u0442\u0435\u043B\u0435\u043C \u043A\u043B\u0438\u043A\u0430 */\n  const onBar = (bar: GanttTimelineDataType) => {\n    if (!bar.id) return {}\n    const barStyles: CSSProperties = selectedBars.length && !selectedBars.includes(bar.id) ? { opacity: 0.3 } : {}\n  \n    return {\n      onClick: (e: MouseEvent<HTMLDivElement>) => handleClickBar(e, bar.id!),\n      style: barStyles\n    }\n  }\n  \n  return (\n    <Gantt\n      onBar={onBar}\n      showTable\n      tableSettings={{\n        cols: [\n          {\n            aggregate: 'count',\n            filter: {\n              enabled: true,\n              items: [],\n              loading: false\n            },\n            name: 'colText',\n            sortable: true,\n            title: '\u0422\u0435\u043A\u0441\u0442',\n            type: 'string'\n          },\n          {\n            name: 'colProgress',\n            render: () => {},\n            title: '\u041F\u0440\u043E\u0433\u0440\u0435\u0441\u0441'\n          }\n        ],\n        data: [\n          {\n            colProgress: '100',\n            colText: '\u0417\u0430\u0434\u0430\u0447\u0430 1 - \u041D\u0430\u0447\u0430\u043B\u044C\u043D\u0430\u044F',\n            endDate: '18.09.2025, 08:05:46',\n            id: 1,\n            startDate: '18.09.2025, 07:05:46'\n          },\n          {\n            colProgress: '75',\n            colText: '\u0417\u0430\u0434\u0430\u0447\u0430 2 - \u0417\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 1',\n            endDate: '18.09.2025, 09:35:46',\n            id: 2,\n            startDate: '18.09.2025, 08:05:46'\n          },\n          {\n            colProgress: '50',\n            colText: '\u0417\u0430\u0434\u0430\u0447\u0430 3 - \u0417\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 2',\n            endDate: '18.09.2025, 11:05:46',\n            id: 3,\n            startDate: '18.09.2025, 09:35:46'\n          },\n          {\n            colProgress: '25',\n            colText: '\u0417\u0430\u0434\u0430\u0447\u0430 4 - \u041F\u0430\u0440\u0430\u043B\u043B\u0435\u043B\u044C\u043D\u0430\u044F',\n            endDate: '18.09.2025, 10:35:46',\n            id: 4,\n            startDate: '18.09.2025, 09:05:46'\n          },\n          {\n            colProgress: '0',\n            colText: '\u0417\u0430\u0434\u0430\u0447\u0430 5 - \u0417\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 3 \u0438 4',\n            endDate: '18.09.2025, 12:05:46',\n            id: 5,\n            startDate: '18.09.2025, 11:05:46'\n          },\n          {\n            colProgress: '0',\n            colText: '\u0412\u0435\u0445\u0430 - \u0424\u0438\u043D\u0430\u043B\u044C\u043D\u0430\u044F',\n            endDate: '18.09.2025, 12:35:46',\n            id: 6,\n            startDate: '18.09.2025, 12:35:46'\n          }\n        ]\n      }}\n      timelineSettings={{\n        timelineData: [\n          {\n            afterBarContent: <Button afterContent=\"+\" iconOnly={<SvgIcon iconName=\"user-circle\" />} size=\"l\" styleType=\"secondary\">+</Button>,\n            afterContent: <MockContent title=\"100%\" />,\n            barColor: 'success',\n            barType: 'default',\n            beforeContent: <MockContent title=\"\u0417\u0430\u0434\u0430\u0447\u0430 1\" />,\n            content: <MockContent iconTitle=\"user-circle\" title=\"\u0417\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0430\"/>,\n            end: new Date('2025-09-18T05:05:46.835Z'),\n            fullness: 100,\n            id: '1.1',\n            linkedTableColumnValue: 1,\n            start: new Date('2025-09-18T04:05:46.835Z')\n          },\n          {\n            afterContent: <MockContent title=\"75%\" />,\n            barColor: 'processing',\n            barType: 'default',\n            beforeContent: <MockContent title=\"\u0417\u0430\u0434\u0430\u0447\u0430 2\" />,\n            content: <MockContent iconTitle=\"user-circle\" title=\"\u0412 \u043F\u0440\u043E\u0446\u0435\u0441\u0441\u0435\"/>,\n            dependingBarIds: [\n              '1.1'\n            ],\n            end: new Date('2025-09-18T06:35:46.835Z'),\n            fullness: 75,\n            id: '2.1',\n            linkedTableColumnValue: 2,\n            start: new Date('2025-09-18T05:05:46.835Z')\n          },\n          {\n            afterContent: <MockContent title=\"50%\" />,\n            barColor: 'warning',\n            barType: 'default',\n            beforeContent: <MockContent title=\"\u0417\u0430\u0434\u0430\u0447\u0430 3\" />,\n            content: <MockContent iconTitle=\"user-circle\" title=\"\u0412 \u043F\u0440\u043E\u0446\u0435\u0441\u0441\u0435\"/>,\n            dependingBarIds: [\n              '2.1'\n            ],\n            end: new Date('2025-09-18T08:05:46.836Z'),\n            fullness: 50,\n            id: '3.1',\n            linkedTableColumnValue: 3,\n            start: new Date('2025-09-18T06:35:46.836Z')\n          },\n          {\n            afterContent: <MockContent title=\"25%\" />,\n            barColor: 'tertiary',\n            barType: 'default',\n            beforeContent: <MockContent title=\"\u0417\u0430\u0434\u0430\u0447\u0430 4\" />,\n            content: <MockContent iconTitle=\"user-circle\" title=\"\u041D\u0430\u0447\u0430\u0442\u0430\"/>,\n            end: new Date('2025-09-18T07:35:46.836Z'),\n            fullness: 25,\n            id: '4.1',\n            linkedTableColumnValue: 4,\n            start: new Date('2025-09-18T06:05:46.836Z')\n          },\n          {\n            afterContent: <MockContent title=\"0%\" />,\n            barColor: 'extra',\n            barType: 'default',\n            beforeContent: <MockContent title=\"\u0417\u0430\u0434\u0430\u0447\u0430 5\" />,\n            content: <MockContent iconTitle=\"user-circle\" title=\"\u041E\u0436\u0438\u0434\u0430\u0435\u0442\"/>,\n            dependingBarIds: [\n              '3.1',\n              '4.1'\n            ],\n            end: new Date('2025-09-18T09:05:46.836Z'),\n            fullness: 0,\n            id: '5.1',\n            linkedTableColumnValue: 5,\n            start: new Date('2025-09-18T08:05:46.836Z')\n          },\n          {\n            afterBarContent: <Button afterContent=\"+\" iconOnly={<SvgIcon iconName=\"user-circle\" />} onClick={() => {}} size=\"l\" styleType=\"secondary\">+</Button>,\n            barType: 'milestone',\n            dependingBarIds: [\n              '5.1'\n            ],\n            id: '6.1',\n            linkedTableColumnValue: 6,\n            start: new Date('2025-09-18T09:35:46.836Z')\n          }\n        ]\n      }}\n    />\n  )  \n}\n";
export default _default;
